package com.biocircular.compostaje.entity;
import jakarta.persistence.*; import java.time.LocalDate; import java.util.*;
@Entity @Table(name="lote") public class Lote { @Id @GeneratedValue private UUID id; @Column(nullable=false,unique=true) private String codigo; @Enumerated(EnumType.STRING) private EstadoLote estado=EstadoLote.EN_PROCESO; @Column(name="fecha_inicio") private LocalDate fechaInicio; @Column(name="fecha_cierre") private LocalDate fechaCierre; @Column(name="creado_por_usuario_externo_id") private UUID responsableId; @ManyToMany @JoinTable(name="lote_ingreso_residuo",joinColumns=@JoinColumn(name="lote_id"),inverseJoinColumns=@JoinColumn(name="ingreso_residuo_id")) private Set<IngresoResiduo> ingresos=new LinkedHashSet<>(); public UUID getId(){return id;} public String getCodigo(){return codigo;} public EstadoLote getEstado(){return estado;} public LocalDate getFechaInicio(){return fechaInicio;} public LocalDate getFechaCierre(){return fechaCierre;} public UUID getResponsableId(){return responsableId;} public Set<IngresoResiduo> getIngresos(){return ingresos;} public void crear(String c,LocalDate f,UUID r){codigo=c;fechaInicio=f;responsableId=r;} public void cerrar(){estado=EstadoLote.FINALIZADO;fechaCierre=LocalDate.now();} public void cancelar(){estado=EstadoLote.CANCELADO;fechaCierre=LocalDate.now();} }
